import { useState } from "react";
import "./components/dropDown.css";
const SismosDropDown = ({ sismos, sismoSeleccionado, setSismoSeleccionado, handleSismoClick}) => {
  const [isOpen, setIsOpen] = useState(false);

  const handleSelection = (sismo) => {
    if (!sismo) {
        setSismoSeleccionado(null);
    } else {
      const sismoId = sismo.id.toString(); // TODO:ver las propiedade del sismo
      setSismoSeleccionado(sismoId);
      //utilizar la funcion principal para mostra el sismo en el mapa
      handleSismoClick(sismo); // Llamar a la función para manejar el clic en el sismo
    }
    setIsOpen(false); // Cerrar el dropdown
  };

  return (
    <div className="dropdown-container">
        <h4 className="dropdown-title">Sismos</h4>
      <button 
        className="dropdown-toggle"
        onClick={() => setIsOpen(!isOpen)}
        aria-haspopup="listbox"
        aria-expanded={isOpen}
      >
        {sismoSeleccionado 
          ? sismos.find(s => s.id.toString() === sismoSeleccionado)?.nombre 
          : "Seleccionar sismo"}
        <span className={`dropdown-arrow ${isOpen ? 'open' : ''}`}>▼</span>
      </button>

      {isOpen && (
        <ul className="dropdown-menu" role="listbox">
          <li
            className={`dropdown-item ${!sismoSeleccionado ? 'active' : ''}`}
            onClick={() => handleSelection(null)}
            role="option"
            aria-selected={!sismoSeleccionado}
          >
            Sismos
          </li>
          {sismos.map((sismo) => (
            <li
              key={sismo.properties.id}
              className={`dropdown-item ${
                sismoSeleccionado === sismo.properties.id.toString() ? 'active' : ''
              }`}
              onClick={() => handleSelection(sismo)}
              role="option"
              aria-selected={sismoSeleccionado === sismo.properties.id.toString()}
            >
              <strong>{sismo.referenciaLocalizacion}</strong> - Magnitud: {sismo.magnitud}
              {sismoSeleccionado === sismo.id.toString() && (
                <span className="selected-icon">✓</span>
              )}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};
// Agrega esta línea al final del archivo:
export default SismosDropDown;
